/**
 * SenseNova U1.5 Lite text-to-image tool.
 *
 * The model is an image-generation model served by an OpenAI-compatible
 * `/v1/images/generations` endpoint; it has no chat-completions route. This
 * plugin exposes it to every DSH agent (root and subagents) as one tool,
 * downloads the generated bytes, saves them in the session working directory,
 * and returns absolute paths plus ready-to-use Markdown.
 */

import { randomUUID } from 'node:crypto'
import { mkdir, writeFile } from 'node:fs/promises'
import { isAbsolute, join, resolve } from 'node:path'
import { defineTool, ToolArgsError } from '@deepseek-ai/dsh-tools'

export const name = 'sensenova-image'
export const inject = ['tools', 'workingDirectory']

const DEFAULT_BASE_URL = 'https://token.sensenova.cn/v1'
const DEFAULT_MODEL = 'sensenova-u1.5-lite'
const DEFAULT_API_KEY_ENV = 'SENSENOVA_API_KEY'
const DEFAULT_OUTPUT_DIR = 'generated-images'
const DEFAULT_REQUEST_TIMEOUT_MS = 180_000
const TOOL_TIMEOUT_MS = 300_000
const MAX_IMAGES = 4

const OUTPUT_FORMATS = {
  png: 'image/png',
  jpeg: 'image/jpeg',
  webp: 'image/webp',
}

function textConfig(config, key, fallback) {
  const value = config?.[key]
  return typeof value === 'string' && value.trim() !== '' ? value.trim() : fallback
}

function numberConfig(config, key, fallback) {
  const value = config?.[key]
  return typeof value === 'number' && Number.isFinite(value) && value > 0 ? value : fallback
}

/** Turn a prompt or requested filename into a short, filesystem-safe stem. */
function safeStem(value, fallback) {
  const cleaned = String(value ?? '')
    .normalize('NFKC')
    .replace(/[^\p{L}\p{N}]+/gu, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 40)
  return cleaned === '' ? fallback : cleaned
}

/** Validate the API's size syntax before spending a request. */
function normalizeSize(raw) {
  const size = typeof raw === 'string' && raw.trim() !== '' ? raw.trim() : '1024x1024'
  if (/^(2k|4k)$/i.test(size)) return size.toUpperCase()
  const match = /^(\d{3,4})x(\d{3,4})$/i.exec(size)
  if (match === null) {
    throw new ToolArgsError(['size must be "2K", "4K", or WIDTHxHEIGHT such as "1024x1024"'])
  }
  const width = Number(match[1])
  const height = Number(match[2])
  const problems = []
  if (width < 512 || width > 4096 || height < 512 || height > 4096) {
    problems.push('width and height must be between 512 and 4096')
  }
  if (width % 32 !== 0 || height % 32 !== 0) problems.push('width and height must be multiples of 32')
  if (Math.max(width, height) / Math.min(width, height) > 3) problems.push('the aspect ratio cannot exceed 3:1')
  if (problems.length > 0) throw new ToolArgsError(problems)
  return `${width}x${height}`
}

/** Resolve the API key from the DSH credential store, then the launch environment. */
async function resolveApiKey(ctx, ref) {
  const credentials = ctx.get('credentials')
  if (credentials !== undefined) {
    const hit = await credentials.resolve(ref)
    if (hit !== undefined && typeof hit.value === 'string' && hit.value.trim() !== '') return hit.value.trim()
  }
  const fromEnvironment = process.env[ref]
  if (typeof fromEnvironment === 'string' && fromEnvironment.trim() !== '') return fromEnvironment.trim()
  throw new Error(
    `sensenova_generate_image: credential ${ref} is not set; store it on the DSH Models page or export it`,
  )
}

/** POST one generation request, combining the tool's cancellation with a request timeout. */
async function requestGeneration({ baseURL, apiKey, body, signal, timeoutMs }) {
  const controller = new AbortController()
  const timer = setTimeout(() => controller.abort(new Error(`request timed out after ${timeoutMs} ms`)), timeoutMs)
  const forwardAbort = () => controller.abort(signal.reason)
  signal.addEventListener('abort', forwardAbort, { once: true })
  try {
    const response = await fetch(`${baseURL.replace(/\/+$/u, '')}/images/generations`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${apiKey}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(body),
      signal: controller.signal,
    })
    const raw = await response.text()
    let payload
    try {
      payload = raw === '' ? undefined : JSON.parse(raw)
    } catch {
      payload = undefined
    }
    if (!response.ok) {
      const detail = payload?.error?.message ?? payload?.message ?? raw.slice(0, 500)
      throw new Error(`sensenova_generate_image: HTTP ${response.status} from /images/generations: ${detail}`)
    }
    if (payload === undefined || !Array.isArray(payload.data) || payload.data.length === 0) {
      throw new Error('sensenova_generate_image: the API returned no image data')
    }
    return payload
  } finally {
    clearTimeout(timer)
    signal.removeEventListener('abort', forwardAbort)
  }
}

/** Read one image's bytes from the API's URL or inline Base64 form. */
async function readImageBytes(item, signal) {
  if (typeof item.b64_json === 'string' && item.b64_json !== '') {
    return Buffer.from(item.b64_json, 'base64')
  }
  if (typeof item.url === 'string' && item.url !== '') {
    const response = await fetch(item.url, { signal })
    if (!response.ok) {
      throw new Error(
        `sensenova_generate_image: could not download the generated image (HTTP ${response.status}); `
        + `the temporary URL is ${item.url}`,
      )
    }
    return Buffer.from(await response.arrayBuffer())
  }
  throw new Error('sensenova_generate_image: the API returned neither url nor b64_json')
}

export function apply(ctx, config) {
  const baseURL = textConfig(config, 'baseURL', DEFAULT_BASE_URL)
  const model = textConfig(config, 'model', DEFAULT_MODEL)
  const apiKeyEnv = textConfig(config, 'apiKeyEnv', DEFAULT_API_KEY_ENV)
  const outputDir = textConfig(config, 'outputDir', DEFAULT_OUTPUT_DIR)
  const requestTimeoutMs = numberConfig(config, 'requestTimeoutMs', DEFAULT_REQUEST_TIMEOUT_MS)

  ctx.tools.register(defineTool({
    name: 'sensenova_generate_image',
    description:
      'Generate one or more images from a text prompt with SenseNova U1.5 Lite (sensenova-u1.5-lite). '
      + 'This is the supported way to use that model: it is an image-generation model, not a chat model. '
      + 'Images are downloaded and saved in the session working directory; the result contains each absolute '
      + 'path, byte size, temporary URL, and ready-to-use Markdown. Put the returned Markdown in your reply so '
      + 'the user can see the image. Use this tool for any text-to-image request, such as illustrations, '
      + 'posters, product shots, or infographics.',
    parameters: {
      prompt: {
        type: 'string',
        required: true,
        description: 'Image description. Chinese and English are both supported; longer, more specific prompts work well.',
      },
      size: {
        type: 'string',
        description: 'Output size: "2K", "4K", or WIDTHxHEIGHT. Width and height must be 512-4096, multiples of 32, and no more than 3:1 apart. Defaults to 1024x1024.',
        default: '1024x1024',
      },
      n: {
        type: 'integer',
        description: `Number of images to generate, 1-${MAX_IMAGES}. Defaults to 1.`,
        default: 1,
      },
      watermark: {
        type: 'boolean',
        description: 'Add the provider watermark. Defaults to false (watermark-free during the free public beta).',
        default: false,
      },
      prompt_extend: {
        type: 'boolean',
        description: 'Let the provider expand and refine the prompt automatically. Defaults to true.',
        default: true,
      },
      output_format: {
        type: 'string',
        enum: ['png', 'jpeg', 'webp'],
        description: 'Saved image format. Defaults to png.',
        default: 'png',
      },
      filename: {
        type: 'string',
        description: 'Optional base name for the saved file; the extension and a uniqueness suffix are added automatically.',
      },
    },
    output: {
      schema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          model: { type: 'string', required: true },
          prompt: { type: 'string', required: true },
          size: { type: 'string', required: true },
          images: {
            type: 'array',
            required: true,
            items: {
              type: 'object',
              additionalProperties: false,
              properties: {
                path: { type: 'string', required: true },
                bytes: { type: 'integer', required: true },
                markdown: { type: 'string', required: true },
                url: { type: 'string' },
              },
            },
          },
        },
      },
      render(_args, value) {
        const lines = [
          `Generated ${value.images.length} image(s) with ${value.model} at ${value.size}.`,
        ]
        for (const image of value.images) {
          lines.push(`- ${image.path} (${image.bytes} bytes)`)
          lines.push(`  Markdown: ${image.markdown}`)
          if (image.url !== undefined) lines.push(`  Temporary URL (24h): ${image.url}`)
        }
        lines.push('Include the Markdown line in your reply so the user can see the image.')
        return [{ type: 'text', text: lines.join('\n') }]
      },
    },
    timeoutMs: TOOL_TIMEOUT_MS,
    async execute(args, exec) {
      exec.signal.throwIfAborted()

      const prompt = args.prompt.trim()
      if (prompt === '') throw new ToolArgsError(['prompt must not be blank'])

      const size = normalizeSize(args.size)
      const n = args.n ?? 1
      if (!Number.isInteger(n) || n < 1 || n > MAX_IMAGES) {
        throw new ToolArgsError([`n must be an integer from 1 to ${MAX_IMAGES}`])
      }
      const format = args.output_format ?? 'png'
      if (!Object.hasOwn(OUTPUT_FORMATS, format)) {
        throw new ToolArgsError(['output_format must be png, jpeg, or webp'])
      }

      const apiKey = await resolveApiKey(ctx, apiKeyEnv)
      const body = {
        model,
        prompt,
        n,
        size,
        output_format: format,
        response_format: 'url',
        watermark: args.watermark ?? false,
        prompt_extend: args.prompt_extend ?? true,
      }

      const payload = await requestGeneration({
        baseURL,
        apiKey,
        body,
        signal: exec.signal,
        timeoutMs: requestTimeoutMs,
      })

      const session = exec.agent?.session
      const cwd = session !== undefined
        ? ctx.workingDirectory.get(session)
        : ctx.workingDirectory.defaultDirectory
      const directory = isAbsolute(outputDir) ? outputDir : resolve(cwd, outputDir)
      await mkdir(directory, { recursive: true })

      const stem = safeStem(args.filename ?? prompt, 'image')
      const stamp = new Date().toISOString().replace(/[:.]/gu, '-')
      const images = []
      for (const [index, item] of payload.data.entries()) {
        const bytes = await readImageBytes(item, exec.signal)
        const path = join(directory, `${stamp}-${stem}-${index + 1}-${randomUUID().slice(0, 8)}.${format}`)
        await writeFile(path, bytes)
        images.push({
          path,
          bytes: bytes.byteLength,
          markdown: `![SenseNova image](<${path}>)`,
          ...(typeof item.url === 'string' && item.url !== '' ? { url: item.url } : {}),
        })
      }

      return {
        model,
        prompt,
        size: typeof payload.size === 'string' && payload.size !== '' ? payload.size : size,
        images,
      }
    },
  }))
}
